    <div class="paid-fields"><label>Amount received (exactly the agreed price)<input name="amount_paid" inputmode="numeric" placeholder="<?= $e(Workshops::money((int)$selected['price'],$selected['currency'])) ?>"></label><label>Payment method<select name="paid_how"><option value="">Choose payment method</option><option value="cash"<?= $mode==='cash'?' selected':'' ?>>Cash</option><option value="transfer">Transfer</option><option value="psoola">Psoola</option></select></label></div>
    <?php if($user['role']==='owner'): ?><label class="inline"><input type="checkbox" name="override" value="1"> Override local capacity limit</label><?php endif; ?><p class="ws-hint">This records the workshop booking and payment. Issue its paid PSOOLA ticket after collecting payment.</p><footer class="ws-book-footer"><button type="button" class="btn ghost" data-ws-close>Cancel</button><button class="btn ws-primary">Book the workshop</button></footer>
